 active=json.loads((ROOT/'research/ACTIVE_RESEARCH.json').read_text());scopes=active['experiment_authority']['current_user_authorized_scopes'];matches=[x for x in scopes if x.get('id')==p['id']+'_VERIFY'];need(len(matches)==1,'verify scope not active');s=matches[0];need(s.get('execution_status')=='RUNNING_FIXED_SCOPE' and s.get('protocol_sha256')==d and s.get('launch_spec_sha256')==sha(args.job_spec) and s.get('resources')==p['verification_resources'] and s.get('limits')==p['verification_limits'],'verify identity')
 j=json.loads(args.job_spec.read_text());v=j['argv'];need(len(v)>1 and v[0]=='env' and v[1].startswith('FFNDS_WORKER_CONFIG='),'profile argv');profile=pathlib.Path(v[1].split('=',1)[1]);expected=['env',v[1],'CUDA_VISIBLE_DEVICES=','taskset','-c',','.join(map(str,j['cpu_affinity'])),str(ROOT/'.venv/bin/python'),'-I','-B']+sys.argv;need(v==expected and profile.is_absolute() and sha(profile)==p['worker_config_sha256'] and j['external_timeout_seconds']==p['verification_resources']['outer_seconds'],'verify exact argv');need(len(j['cpu_affinity'])==1 and j['id']==p['id']+'_VERIFY' and j['protocol_sha256']==d and j['driver_argv']==sys.argv and pathlib.Path(j['cwd']).resolve()==ROOT and sorted(os.sched_getaffinity(0))==j['cpu_affinity'] and os.environ.get('CUDA_VISIBLE_DEVICES')=='' and pathlib.Path(j['protocol_path']).resolve()==args.protocol.resolve() and pathlib.Path(j['hf_root']).resolve()==args.hf_root.resolve(),'verify job')
 hf=args.hf_root.resolve();out=(hf/p['output_HF_relative']).resolve();run=out/'RUN.json';exitp=out.parent/'EXIT_RECEIPT.json';dest=pathlib.Path(j['run_json']).resolve();need(dest.is_relative_to(hf) and not dest.exists() and dest.parent.parent==pathlib.Path(j['output_dir']).resolve(),'verify destination');dest.parent.mkdir(parents=True);r={'id':j['id'],'protocol_sha256':d,'job_spec_sha256':sha(args.job_spec),'status':'STARTED','predebited_bytes':0,'completed_bytes':0,'inflight':None,'automatic_retry':False};write(dest,r);started=time.monotonic();old_handler=signal.signal(signal.SIGALRM,lambda *_:(_ for _ in ()).throw(TimeoutError('verification wall')));signal.alarm(p['verification_resources']['wall_seconds'])
 try:
  review_ref=s['review'];review_path=(ROOT/review_ref['path']).resolve();need(review_path.is_relative_to(ROOT) and review_path.stat().st_size==review_ref['bytes'] and sha(review_path)==review_ref['sha256'],'review binding');review=json.loads(review_path.read_text());need(review['state']=='REVIEWER_RECHECK_APPROVED' and review['scope_id']==p['id'] and review['protocol_sha256']==d and review['verification_job_spec_sha256']==sha(args.job_spec) and review['author_agent_id']!=review['reviewer_agent_id'] and review['critical_source_hashes']=={x['path']:x['sha256'] for x in p['repo_sources']},'review identity')
  files={}
  for name,path in [('RUN',run),('EXIT',exitp)]:
   size=path.stat().st_size;need(size<=16<<20 and r['predebited_bytes']+size<=32<<20,'verify byte bound');r['predebited_bytes']+=size;r['inflight']={'name':name,'bytes':size,'completed':'UNKNOWN'};write(dest,r);data=path.read_bytes();need(len(data)==size,'short read');files[name]={'data':json.loads(data),'sha256':hashlib.sha256(data).hexdigest(),'bytes':size};r['completed_bytes']+=size;r['inflight']=None;write(dest,r)
  for source in p['repo_sources']:
   q=(ROOT/source['path']).resolve();need(q.is_relative_to(ROOT) and q.stat().st_size==source['bytes'] and r['predebited_bytes']+source['bytes']<=32<<20,'source identity/budget');r['predebited_bytes']+=source['bytes'];r['inflight']={'name':source['path'],'bytes':source['bytes'],'completed':'UNKNOWN'};write(dest,r);need(sha(q)==source['sha256'],'source SHA');r['completed_bytes']+=source['bytes'];r['inflight']=None;write(dest,r)
  sys.path.insert(0,str(ROOT/'tools'));import worker_identity;worker_identity.require_worker();need(sha(worker_identity.private_config_path())==p['worker_config_sha256'],'verify worker')
  a=files['RUN']['data'];e=files['EXIT']['data'];need(a['id']==p['id'] and a['protocol_sha256']==d and a['status']=='COMPLETE_DIAGNOSTIC' and e['id']==p['id'] and e['child_returncode']==0 and e['process_exited'] and not e['timeout'] and e['run_sha256']==files['RUN']['sha256'] and e['protocol_sha256']==d,'actual GPU exit')
  cpu=a['CPU_preflight'];
  for name in ('RUN','EXIT'):
   b=cpu[name];q=(hf/b['path']).resolve();need(q.is_relative_to(hf) and q.stat().st_size==b['bytes'] and r['predebited_bytes']+b['bytes']<=32<<20,'CPU proof budget');r['predebited_bytes']+=b['bytes'];r['inflight']={'name':'CPU_'+name,'bytes':b['bytes'],'completed':'UNKNOWN'};write(dest,r);raw=q.read_bytes();need(len(raw)==b['bytes'] and hashlib.sha256(raw).hexdigest()==b['sha256'],'CPU proof SHA');files['CPU_'+name]={'data':json.loads(raw),'sha256':b['sha256']};r['completed_bytes']+=b['bytes'];r['inflight']=None;write(dest,r)
  cr=files['CPU_RUN']['data'];ce=files['CPU_EXIT']['data'];need(cr['status']=='PASS_ISOLATED_ENTRY_CPU_PREFLIGHT' and cr['protocol_sha256']==d and ce['child_returncode']==0 and ce['process_exited'] and ce['run_sha256']==files['CPU_RUN']['sha256'] and ce['spec_sha256']==cr['job_spec_sha256']==review['cpu_job_spec_sha256'],'CPU actual EXIT proof')
  need(cr['master_sha_completed_bytes']==p['checkpoint']['bytes'] and cr['master_sha_inflight']=='NONE' and cr['cuda_initialized'] is False,'master preflight');need(a['source_hash_inflight']=='NONE' and a['source_hash_predebit_bytes']==a['source_hash_completed_bytes'] and a['backend_hash_inflight']=='NONE' and a['backend_hash_predebit_bytes']==a['backend_hash_completed_bytes'] and a['environment_inflight']=='NONE' and a['environment_predebit_bytes']==a['environment_completed_bytes'] and a['instrumented_gpu_other_bytes']+a['predebited']['scientific_read_bytes']<=p['read_budgets']['gpu_instrumented_bytes_max'],'source/environment/read ledger');need(a['peak_GPU_reserved_bytes']<p['resources']['gpu_reserved_bytes'] and a['peak_host_RSS_bytes']<p['resources']['host_peak_rss_bytes'] and a['wall_seconds']<=p['resources']['wall_seconds'] and not a['monitor']['violations'],'GPU resource outcome');validate_typed(a,p['operation_limits']);need(a['mask_sha256']['A']==p['previous_mask_sha256']['p64'],'prior mask differs');need(e['spec_sha256']==a['job_spec_sha256']==review['job_spec_sha256'],'GPU spec differs')
  r.update(status='PASS_HISTORY_ENCODING_TYPED_RESULTS_EXIT_PENDING',parent_RUN_sha256=files['RUN']['sha256'],parent_EXIT_sha256=files['EXIT']['sha256'],wall_seconds=time.monotonic()-started);write(dest,r)
 except BaseException as e:
  r.update(status='FAILED_NO_RETRY',error_type=type(e).__name__,error=str(e)[:1000]);write(dest,r);raise
